fn measure(s: &String) -> usize {
    s.len()
}

fn main() {
    let name = String::from("ferris");
    let n = measure(&name);
    println!("{n} {name}");
}

fn add_period(s: &mut String) {
    s.push_str(".");
}

fn main() {
    let mut greeting = String::from("hello");
    add_period(&mut greeting);
    add_period(&mut greeting);
    println!("{greeting}");
}

fn main() {
    let mut text = String::from("hi");
    let a = &text;
    println!("first look: {a}");

    let b = &mut text;
    b.push_str("!");
    println!("now: {b}");
}

fn first_two(s: &str) -> &str {
    &s[0..2]
}

fn main() {
    let word = String::from("hello");
    let part = &word[0..2];
    let whole = &word[..];
    println!("{part} {whole} {}", part.len());
    println!("{}", first_two(&word));
}

